package dev.veltraph.client.navigation;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class MaintenanceAuthorityReadFenceTest {
    @Test void sameEpochRawPublicationAfterEarlierOperandsCannotPassFinalNativeFence(){long[] serial={9};assertFalse(MaintenanceAuthorityReadFence.afterReads(true,()->{serial[0]=10;return true;},()->serial[0]==9));}
    @Test void replacementProviderOrEndedClosureCannotPassByBeingMerelyNonNull(){Object original=new Object();Object[] current={original};assertFalse(MaintenanceAuthorityReadFence.afterReads(true,()->{current[0]=new Object();return current[0]==original;},()->true));current[0]=null;assertFalse(MaintenanceAuthorityReadFence.afterReads(true,()->current[0]==original,()->true));}
    @Test void lastSourceReadChangingPwcStoreOrLockIsCheckedByNativeLeaf(){Object old=new Object();Object[] state={old,old,old};assertFalse(MaintenanceAuthorityReadFence.afterReads(true,()->{state[0]=new Object();return true;},()->state[0]==old&&state[1]==old&&state[2]==old));state[0]=old;assertFalse(MaintenanceAuthorityReadFence.afterReads(true,()->{state[1]=new Object();return true;},()->state[0]==old&&state[1]==old&&state[2]==old));}
    @Test void lastSourceCallbackChangingRegistryOrLockWithoutPublicationStillRejects(){Object original=new Object();Object[] registry={original};String[] lock={"helper"};assertFalse(MaintenanceAuthorityReadFence.afterReads(true,()->{registry[0]=new Object();return true;},()->registry[0]==original&&"helper".equals(lock[0])));registry[0]=original;assertFalse(MaintenanceAuthorityReadFence.afterReads(true,()->{lock[0]="foreign";return true;},()->registry[0]==original&&"helper".equals(lock[0])));}
    @Test void cameraRoleReplacementWithoutEpochOrSerialChangeIsNotAbsence(){Object token=new Object();Object[] camera={token};assertFalse(MaintenanceAuthorityReadFence.afterReads(true,()->{camera[0]=new Object();return true;},()->camera[0]==token));camera[0]=null;assertFalse(MaintenanceAuthorityReadFence.afterReads(true,()->{camera[0]=token;return true;},()->camera[0]==null));}
    @Test void observerExceptionOrInitialRejectionNeverGrantsPermission(){assertFalse(MaintenanceAuthorityReadFence.afterReads(true,()->{throw new AssertionError("observer");},()->true));boolean[] touched={false};assertFalse(MaintenanceAuthorityReadFence.afterReads(false,()->{touched[0]=true;return true;},()->true));assertFalse(touched[0]);}
}
